# Ensure both lunch_start_dt and now_dt are datetime.datetime objects (not date or other types)
if type(lunch_start) == "str":
    # Try parsing with seconds if present, otherwise without
    try:
        lunch_start_dt = datetime.strptime(lunch_start, "%Y-%m-%d %H:%M:%S")
    except Exception:
        lunch_start_dt = datetime.strptime(lunch_start, "%Y-%m-%d %H:%M")
elif type(lunch_start) == "date":
    # Convert date to datetime at midnight
    lunch_start_dt = datetime.combine(lunch_start, datetime.strptime("00:00", "%H:%M").time())
else:
    lunch_start_dt = lunch_start

if type(now) == "str":
    try:
        now_dt = datetime.strptime(now, "%Y-%m-%d %H:%M:%S")
    except Exception:
        now_dt = datetime.strptime(now, "%Y-%m-%d %H:%M")
elif type(now) == "date":
    now_dt = datetime.combine(now, datetime.strptime("00:00", "%H:%M").time())
else:
    now_dt = now

# Now both are datetime.datetime objects
if lunch_start_dt < now_dt:
    print("00:00")
else:
    delta = lunch_start_dt - now_dt
    hours, remainder = divmod(int(delta.total_seconds()), 3600)
    minutes = remainder // 60
    print("{:02d}:{:02d}".format(hours, minutes))
